using System.Collections;
using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "CorruptedLightningAction", menuName = "Data/Battle/Battle Actions/Purification Actions/Corrupted Lightning Action")]
public class CorruptedLightningAction : LightningAction
{
	[Header("Action Specifics")]
	[SerializeField]
	protected CorruptAction corruptAction;

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(SingleTargetCast(target, amount, base.CorruptPurifyAmountWithModifier, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	public void CastTargetAmountWithCorruptionPurifyModifierEnum(GameObject target, int amount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(SingleTargetCast(target, amount, base.CorruptPurifyAmountWithModifier, source, corruptionPurifyModifierEnum));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	public void SingleTargetCastDefault(GameObject target, int timesAmount, int corruptAmount, GameObject source)
	{
		ActivateSafeCriticalOmen(source);
		GameStateManager instance = ReferenceSingleton<GameStateManager>.Instance;
		instance.ActionsQueueState.EnqueueAction(SingleTargetCast(target, timesAmount, corruptAmount, source));
		instance.SetState(instance.ActionsQueueState);
	}

	public void CastTargetAmountEnqueueBeforeMainActionAction(GameObject target, int amount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueBeforeMainActionAction(SingleTargetCast(target, amount, base.CorruptPurifyAmountWithModifier, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	public IEnumerator SingleTargetCast(GameObject target, int timesAmount, int corruptAmount, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE)
	{
		yield return InvokeAlternatives.WaitOneFrame();
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		for (int i = 0; i < timesAmount; i++)
		{
			corruptAction.CastTargetAmountXTime(target, corruptAmount, source, corruptionPurifyModifierEnum);
			if (i == 0)
			{
				SingleTargetCastAfterFirstCorruption(source);
			}
			yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
		}
	}

	public virtual void SingleTargetCastAfterFirstCorruption(GameObject source)
	{
	}

	public override void AreaCastTargetAmount(List<GameObject> targets, int actionAmount, GameObject source)
	{
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(MultipleTargetCast(targets, actionAmount, source));
		ReferenceSingleton<GameStateManager>.Instance.SetState(ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState);
	}

	private IEnumerator MultipleTargetCast(List<GameObject> targets, int timesAmount, GameObject source)
	{
		yield return InvokeAlternatives.WaitOneFrame();
		CheckCancelAutoOnDiceCastedOnRuneCasted(source);
		for (int i = 0; i < timesAmount; i++)
		{
			corruptAction.AreaCastTargetAmountXTime(targets, base.CorruptPurifyAmountWithModifier, source);
			yield return new WaitForSeconds(base.DelayBetweenCorruptPurify);
		}
	}
}
